CREATE TABLE public.sales_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), owner_id uuid NOT NULL DEFAULT auth.uid(), lead_id uuid NOT NULL REFERENCES public.leads(id), kind text NOT NULL CHECK(kind IN ('Quotation','Order','Invoice')), number text NOT NULL DEFAULT ('DOC-' || upper(substr(gen_random_uuid()::text,1,8))), parent_id uuid REFERENCES public.sales_documents(id), items jsonb NOT NULL DEFAULT '[]', total numeric(14,2) NOT NULL CHECK(total>=0), status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Issued','Cancelled')), due_date date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.sales_documents TO authenticated; GRANT ALL ON public.sales_documents TO service_role;
ALTER TABLE public.sales_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_documents ON public.sales_documents FOR ALL TO authenticated USING(owner_id=auth.uid() AND organization_id=public.crm_org()) WITH CHECK(owner_id=auth.uid() AND organization_id=public.crm_org() AND EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id AND owner_id=auth.uid()));
CREATE TABLE public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), owner_id uuid NOT NULL DEFAULT auth.uid(), invoice_id uuid NOT NULL REFERENCES public.sales_documents(id), amount numeric(14,2) NOT NULL CHECK(amount>0), method text NOT NULL DEFAULT 'Bank transfer' CHECK(method IN ('Bank transfer','Cash','UPI','Cheque')), reference text NOT NULL, paid_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.payments TO authenticated; GRANT ALL ON public.payments TO service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_payment_read ON public.payments FOR SELECT TO authenticated USING(owner_id=auth.uid() AND organization_id=public.crm_org());
CREATE POLICY own_payment_insert ON public.payments FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND organization_id=public.crm_org());
CREATE FUNCTION public.validate_sales_document() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE subtotal numeric:=0; item jsonb; parent public.sales_documents; BEGIN
IF jsonb_typeof(NEW.items)<>'array' OR jsonb_array_length(NEW.items)=0 THEN RAISE EXCEPTION 'Add at least one line item'; END IF;
FOR item IN SELECT * FROM jsonb_array_elements(NEW.items) LOOP IF length(trim(item->>'name'))=0 OR (item->>'quantity')::numeric<=0 OR (item->>'price')::numeric<0 THEN RAISE EXCEPTION 'Invalid line item'; END IF; subtotal:=subtotal+round((item->>'quantity')::numeric*(item->>'price')::numeric,2); END LOOP;
IF NEW.total<>subtotal THEN RAISE EXCEPTION 'Document total must match its line items'; END IF;
IF NEW.parent_id IS NOT NULL THEN SELECT * INTO parent FROM public.sales_documents WHERE id=NEW.parent_id; IF parent.id IS NULL OR parent.owner_id<>NEW.owner_id OR parent.organization_id<>NEW.organization_id OR parent.lead_id<>NEW.lead_id OR parent.status='Cancelled' OR NOT ((NEW.kind='Order' AND parent.kind='Quotation') OR (NEW.kind='Invoice' AND parent.kind='Order')) THEN RAISE EXCEPTION 'Invalid document link'; END IF; END IF;
IF TG_OP='UPDATE' THEN IF NEW.items IS DISTINCT FROM OLD.items OR NEW.total<>OLD.total OR NEW.kind<>OLD.kind OR NEW.parent_id IS DISTINCT FROM OLD.parent_id OR NEW.lead_id<>OLD.lead_id OR NEW.owner_id<>OLD.owner_id OR NEW.organization_id<>OLD.organization_id THEN RAISE EXCEPTION 'Document financial details are immutable'; END IF; IF NEW.status='Cancelled' AND (EXISTS(SELECT 1 FROM public.payments WHERE invoice_id=OLD.id) OR EXISTS(SELECT 1 FROM public.sales_documents WHERE parent_id=OLD.id AND status<>'Cancelled')) THEN RAISE EXCEPTION 'Cannot cancel a paid or linked document'; END IF; END IF;
RETURN NEW; END $$;
CREATE TRIGGER validate_document BEFORE INSERT OR UPDATE ON public.sales_documents FOR EACH ROW EXECUTE FUNCTION public.validate_sales_document();
CREATE FUNCTION public.validate_payment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE invoice public.sales_documents; received numeric; BEGIN SELECT * INTO invoice FROM public.sales_documents WHERE id=NEW.invoice_id FOR UPDATE; IF invoice.id IS NULL OR invoice.kind<>'Invoice' OR invoice.status<>'Issued' OR invoice.owner_id<>NEW.owner_id OR invoice.organization_id<>NEW.organization_id THEN RAISE EXCEPTION 'Select an issued invoice in your workspace'; END IF; SELECT coalesce(sum(amount),0) INTO received FROM public.payments WHERE invoice_id=NEW.invoice_id; IF NEW.amount>invoice.total-received THEN RAISE EXCEPTION 'Payment exceeds invoice balance'; END IF; IF length(trim(NEW.reference))=0 THEN RAISE EXCEPTION 'Payment reference is required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_payment BEFORE INSERT ON public.payments FOR EACH ROW EXECUTE FUNCTION public.validate_payment();
ALTER TABLE public.organizations ADD COLUMN followup_enabled boolean NOT NULL DEFAULT false, ADD COLUMN followup_days integer NOT NULL DEFAULT 1 CHECK(followup_days BETWEEN 1 AND 365), ADD COLUMN bank_details text NOT NULL DEFAULT '';
CREATE POLICY admin_roles_read ON public.user_roles FOR SELECT TO authenticated USING(organization_id=public.crm_org());
CREATE TABLE public.location_checkins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), organization_id uuid NOT NULL DEFAULT public.crm_org() REFERENCES public.organizations(id), lead_id uuid REFERENCES public.leads(id), latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), accuracy double precision NOT NULL CHECK(accuracy>=0), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.location_checkins TO authenticated; GRANT ALL ON public.location_checkins TO service_role;
ALTER TABLE public.location_checkins ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_checkins ON public.location_checkins FOR ALL TO authenticated USING(owner_id=auth.uid() AND organization_id=public.crm_org()) WITH CHECK(owner_id=auth.uid() AND organization_id=public.crm_org() AND (lead_id IS NULL OR EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id AND owner_id=auth.uid())));
CREATE FUNCTION public.crm_auto_followup() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE days integer; enabled boolean; BEGIN SELECT followup_days,followup_enabled INTO days,enabled FROM public.organizations WHERE id=NEW.organization_id; IF enabled THEN INSERT INTO public.tasks(organization_id,owner_id,lead_id,title,due_at,priority) VALUES(NEW.organization_id,NEW.owner_id,NEW.id,'Follow up: '||NEW.name,now()+make_interval(days=>days),'Medium'); END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_lead_followup AFTER INSERT ON public.leads FOR EACH ROW EXECUTE FUNCTION public.crm_auto_followup();
CREATE INDEX payments_invoice_idx ON public.payments(invoice_id); CREATE INDEX sales_parent_idx ON public.sales_documents(parent_id);